import { useState } from "react";
export default function Inputsatate() {
  const [input, setinput] = useState("");
  function Value(event) {
    setinput(event.target.Value);
  }
  return (
    <>
      <h1>inter</h1>
      <input value={input} onChange={Value}></input>
    </>
  );
}
